import 'package:easy_flavor/easy_flavor.dart';
import 'package:easy_flavor/src/ios/ios_files.dart';
import 'package:test/test.dart';

import '../helpers/fixtures.dart';

void main() {
  test(
    'xcconfig includes the per-configuration Pods file and sets identifiers',
    () {
      const flavor = FlavorSpec(
        name: 'dev',
        appName: 'A // B',
        androidId: 'com.a.dev',
        iosBundleId: 'com.a.dev',
      );
      expect(renderXcconfig('Debug', flavor), '''
// Generated by easy_flavor. Do not edit; change easy_flavor.yaml instead.
#include? "Pods/Target Support Files/Pods-Runner/Pods-Runner.debug-dev.xcconfig"
#include "Generated.xcconfig"

PRODUCT_BUNDLE_IDENTIFIER = com.a.dev
APP_DISPLAY_NAME = A /\$()/ B
''');
    },
  );

  group('Info.plist', () {
    test('fresh template', () {
      final plist = read(copyFixture('fresh_kts'), infoPlistFile);
      final (out, previous) = withDisplayNameSetting(plist);
      expect(previous, 'Fresh App');
      expect(
        out,
        contains(
          '<key>CFBundleDisplayName</key>\n\t<string>\$(APP_DISPLAY_NAME)</string>',
        ),
      );
      expect(withDisplayNameSetting(out).$1, out);
      expect(withDisplayNameSetting(out).$2, isNull);
    });

    test('adds the key when missing', () {
      const plist =
          '<?xml version="1.0"?>\n<plist version="1.0">\n<dict>\n\t<key>A</key>\n\t<string>b</string>\n</dict>\n</plist>\n';
      expect(
        withDisplayNameSetting(plist).$1,
        contains(
          '<dict>\n\t<key>CFBundleDisplayName</key>\n\t<string>\$(APP_DISPLAY_NAME)</string>\n\t<key>A</key>',
        ),
      );
    });
  });

  test('scheme uses the flavor configurations and keeps everything else', () {
    final runner = read(copyFixture('fresh_kts'), runnerScheme);
    final scheme = renderScheme(runner, 'dev');
    expect(isFlavorScheme(scheme, 'dev'), isTrue);
    expect(isFlavorScheme(runner, 'dev'), isFalse);
    for (final c in ['Debug-dev', 'Release-dev', 'Profile-dev']) {
      expect(scheme, contains('buildConfiguration = "$c"'));
    }
    expect(scheme.replaceAll('-dev"', '"'), runner);
  });

  group('Podfile', () {
    late String template;
    setUp(() => template = read(copyFixture('cocoapods'), podfile));
    const configs = [
      'Debug',
      'Release',
      'Profile',
      'Debug-dev',
      'Release-dev',
      'Profile-dev',
    ];

    test('keeps existing order and appends flavor configurations', () {
      final out = withPodfileConfigurations(template, configs);
      expect(
        out,
        contains('''
project 'Runner', {
  'Debug' => :debug,
  'Profile' => :release,
  'Release' => :release,
  'Debug-dev' => :debug,
  'Release-dev' => :release,
  'Profile-dev' => :release,
}'''),
      );
      expect(withPodfileConfigurations(out, configs), out);
    });

    test('drops removed flavors but keeps custom entries', () {
      final custom = template.replaceFirst(
        "  'Release' => :release,\n",
        "  'Release' => :release,\n  'Staging' => :release,\n",
      );
      final withDev = withPodfileConfigurations(custom, configs);
      final without = withPodfileConfigurations(
        withDev,
        configs.take(3).toList(),
      );
      expect(without, isNot(contains('-dev')));
      expect(without, contains("'Staging' => :release"));
    });

    test('adds a map when missing', () {
      final out = withPodfileConfigurations(
        "platform :ios, '15.0'\n\ntarget 'Runner' do\nend\n",
        configs.take(3).toList(),
      );
      expect(
        out,
        startsWith(
          "platform :ios, '15.0'\n\nproject 'Runner', {\n  'Debug' => :debug,",
        ),
      );
    });
  });
}
